body{margin:0;font-family:'Open Sans','Inter','Segoe UI',Arial,sans-serif;background:transparent;color:#e2e8f0;}
.scroll{max-height:820px;overflow:auto;border:1px solid #334155;border-radius:6px;}
.tbl{width:100%;border-collapse:collapse;font-size:13px;}
.tbl th,.tbl td{padding:7px 10px;text-align:left;border-bottom:1px solid #334155;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}
.tbl th{position:sticky;top:0;background:#0f172a;color:#cbd5e1;font-size:11px;text-transform:uppercase;letter-spacing:.04em;font-weight:700;z-index:1;}
.tbl td.num,.tbl th.num{text-align:right;font-variant-numeric:tabular-nums;}
.tbl tbody tr:nth-child(even) td{background:#111c30;}
.tbl tr.best td{background:rgba(16,185,129,.16) !important;}
.tbl tr.best td:first-child{box-shadow:inset 3px 0 0 #10b981;}
td.star{color:#fbbf24;text-align:center;width:26px;}
td.pos{color:#34d399;font-weight:700;}
td.neg{color:#f87171;}
.code{color:#94a3b8;font-size:11px;}
td.status.err{color:#f87171;}
td.empty{color:#94a3b8;text-align:center;padding:18px;}
details.usage{margin-top:12px;border:1px solid #334155;border-radius:6px;padding:8px 12px;background:#1e293b;}
details.usage summary{cursor:pointer;color:#cbd5e1;font-size:12px;font-weight:600;user-select:none;}
details.usage .tbl{margin-top:10px;}
.cat{padding:1px 7px;border-radius:10px;font-size:11px;font-weight:600;white-space:nowrap;}
.cat-rc{background:rgba(16,185,129,.18);color:#34d399;}
.cat-rd{background:rgba(148,163,184,.18);color:#cbd5e1;}
.cat-ot{background:rgba(148,163,184,.12);color:#94a3b8;}
.tag-mod{background:rgba(59,130,246,.2);color:#60a5fa;padding:1px 7px;border-radius:10px;font-size:11px;font-weight:600;}
td.ctr,th.ctr{text-align:center;}
.tou{background:rgba(234,179,8,.18);color:#fbbf24;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:700;}
.footnote{color:#94a3b8;font-size:11px;margin:6px 2px 0;font-style:italic;}
.da{background:rgba(168,85,247,.2);color:#c084fc;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:700;}
.rtp{background:rgba(45,212,191,.18);color:#2dd4bf;padding:1px 6px;border-radius:10px;font-size:10px;font-weight:700;}

