function fmt(n){ if(n==null||isNaN(n)) return '—'; var v=Number(n); return (v<0?'-':'')+'$'+Math.abs(v).toFixed(2).replace(/\B(?=(\d{3})+(?!\d))/g,','); }
function fmtPct(n){ if(n==null||isNaN(n)) return '—'; var v=Number(n); return (v>0?'+':'')+v.toFixed(1)+'%'; }
function fmtNum(n){ if(n==null||isNaN(n)) return '—'; return Number(n).toLocaleString(undefined,{maximumFractionDigits:0}); }
function esc(s){ return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function sCls(v){ if(v==null) return ''; return v>0?'pos':(v<0?'neg':''); }

function renderRows(rows){
  if(!rows.length) return '<tr><td colspan="11" class="empty">No tariffs modeled yet. Pick a customer and location.</td></tr>';
  return rows.map(function(r){
    var best = r.best ? 'best' : '';
    var tariff = esc(r.tariff) + (r.code ? ' <span class="code">('+esc(r.code)+')</span>' : '') + (r.tou ? ' <span class="tou" title="Time-of-use rate \u2014 modeled from a default load profile; treat as an estimate">TOU*</span>' : '') + (r.da ? ' <span class="da" title="Direct Access \u2014 requires a competitive energy supplier, not just a utility rate change">DA</span>' : '') + (r.rtp ? ' <span class="rtp" title="Hourly / real-time pricing \u2014 savings depend on shifting load to cheaper hours; modeled on a default profile, treat as an estimate">RTP*</span>' : '');
    return '<tr class="'+best+'">'
      + '<td class="num">'+esc(r.rank)+'</td>'
      + '<td class="star">'+(r.best?'★':'')+'</td>'
      + '<td title="'+esc(r.utility)+'">'+esc(r.utility)+'</td>'
      + '<td title="'+esc(r.tariff)+'">'+tariff+'</td>'
      + '<td class="num">'+fmt(r.modeled_annual)+'</td>'
      + '<td class="num">'+fmt(r.modeled_energy)+'</td>'
      + '<td class="num">'+fmt(r.modeled_demand)+'</td>'
      + '<td class="num">'+fmt(r.actual_annual)+'</td>'
      + '<td class="num '+sCls(r.annual_savings)+'">'+fmt(r.annual_savings)+'</td>'
      + '<td class="num '+sCls(r.annual_savings)+'">'+fmtPct(r.savings_pct)+'</td>'
      + '<td class="status '+(r.status==='Error'?'err':'')+'">'+esc(r.status)+'</td>'
      + '</tr>';
  }).join('');
}

function renderUsage(usage){
  if(!usage.length) return '';
  var body = usage.map(function(u){
    return '<tr><td>'+esc(u.month)+'</td>'
      + '<td class="num">'+fmtNum(u.kwh)+'</td>'
      + '<td class="num">'+fmtNum(u.kw)+'</td>'
      + '<td class="num">'+fmt(u.actual_charges)+'</td></tr>';
  }).join('');
  return '<details class="usage"><summary>12-month usage profile used for modeling ('+usage.length+' months)</summary>'
    + '<table class="tbl"><thead><tr><th>Month</th><th class="num">kWh</th><th class="num">kW</th><th class="num">Actual $</th></tr></thead>'
    + '<tbody>'+body+'</tbody></table></details>';
}

function renderAllTariffs(list){
  if(!list.length) return '';
  var body = list.map(function(t){
    var badge = t.modeled ? '<span class="tag-mod">modeled</span>' : '';
    var catCls = t.category==='Rate Class' ? 'cat-rc' : (t.category==='Rider/Surcharge' ? 'cat-rd' : 'cat-ot');
    return '<tr>'
      + '<td>'+esc(t.utility)+'</td>'
      + '<td>'+esc(t.name)+(t.code?' <span class="code">('+esc(t.code)+')</span>':'')+(t.tou?' <span class="tou">TOU*</span>':'')+(t.da?' <span class="da">DA</span>':'')+(t.rtp?' <span class="rtp">RTP*</span>':'')+'</td>'
      + '<td><span class="cat '+catCls+'">'+esc(t.category)+'</span></td>'
      + '<td>'+esc(t.type)+'</td>'
      + '<td>'+esc(t.customerClass)+'</td>'
      + '<td class="ctr">'+badge+'</td>'
      + '</tr>';
  }).join('');
  return '<details class="usage"><summary>All tariffs returned by Arcadia ('+list.length+') — includes riders/surcharges not modeled</summary>'
    + '<table class="tbl"><thead><tr><th>Utility</th><th>Tariff</th><th>Category</th><th>Type</th><th>Customer Class</th><th class="ctr">Modeled</th></tr></thead>'
    + '<tbody>'+body+'</tbody></table></details>';
}

function render(model){
  var rows = (model && Array.isArray(model.rows)) ? model.rows : [];
  var usage = (model && Array.isArray(model.usage)) ? model.usage : [];
  var allTariffs = (model && Array.isArray(model.allTariffs)) ? model.allTariffs : [];
  var root = document.getElementById('root');
  if(!root) return;
  root.innerHTML =
    '<div class="scroll"><table class="tbl rank"><thead><tr>'
    + '<th class="num">#</th><th></th><th>Utility</th><th>Tariff</th>'
    + '<th class="num">Modeled $/yr</th><th class="num">Energy $/yr</th><th class="num">Demand $/yr</th><th class="num">Actual $/yr</th>'
    + '<th class="num">Savings $/yr</th><th class="num">Savings %</th><th>Status</th>'
    + '</tr></thead><tbody>'+renderRows(rows)+'</tbody></table></div>'
    + (rows.some(function(r){return r.tou;}) ? '<div class="footnote">TOU* = time-of-use rate; modeled from a default load profile (actual interval usage not applied) \u2014 treat as an estimate.</div>' : '')
    + (rows.some(function(r){return r.da;}) ? '<div class="footnote">DA = Direct Access; savings require contracting a competitive energy supplier, not just a utility rate change.</div>' : '')
    + (rows.some(function(r){return r.rtp;}) ? '<div class="footnote">RTP* = hourly / real-time / day-ahead pricing; savings depend heavily on shifting load to cheaper hours and are modeled on a default profile \u2014 treat as an estimate.</div>' : '')
    + renderUsage(usage)
    + renderAllTariffs(allTariffs);
}

appsmith.onReady(function(){ render(appsmith.model); appsmith.onModelChange(render); });

